package hk.local.enginex7;
import java.io.*;import java.util.*;

/** Deterministic pre-limiter synthesis evidence, independent of physical speaker loudness. */
public final class AudioTuningProbe {
 static final int RATE=48000,BLOCK=480;
 static EngineModel.Frame frame(double rpm,double load,int bov){return new EngineModel.Frame(Profile.get("subaru"),rpm,rpm,0,0,load,.7,1,0,bov,0,false,true,false,true,"run");}
 static double rms(float[] x,int from,int to){double s=0;for(int i=from;i<to;i++)s+=x[i]*x[i];return Math.sqrt(s/(to-from));}
 static float[] dry(double rpm){EngineSynth s=new EngineSynth(RATE);float[] block=new float[BLOCK],result=new float[RATE*3];EngineModel.Frame f=frame(rpm,.08,0);for(int k=0;k<400;k++){s.render(f,block);if(k>=100)System.arraycopy(block,0,result,(k-100)*BLOCK,BLOCK);}return result;}
 static float[] bov(){return bov(5000);}
 static float[] bov(double releaseRpm){EngineSynth a=new EngineSynth(RATE),b=new EngineSynth(RATE);float[] x=new float[BLOCK],y=new float[BLOCK],result=new float[RATE*4];for(int k=0;k<100;k++){a.render(frame(releaseRpm,.08,0),x);b.render(frame(releaseRpm,.08,0),y);}for(int k=0;k<400;k++){a.render(frame(releaseRpm,.08,1),x);b.render(frame(releaseRpm,.08,0),y);for(int i=0;i<BLOCK;i++)result[k*BLOCK+i]=x[i]-y[i];}return result;}
 static double body(float[] x){double fast=0,slow=0,sum=0;double a=1-Math.exp(-2*Math.PI*220/RATE),b=1-Math.exp(-2*Math.PI*55/RATE);for(float v:x){fast+=(v-fast)*a;slow+=(v-slow)*b;double y=fast-slow;sum+=y*y;}return Math.sqrt(sum/x.length);}
 static double highRatio(float[] x){double low=0,high=0,total=0,k=1-Math.exp(-2*Math.PI*1200/RATE);for(float v:x){low+=(v-low)*k;high+=(v-low)*(v-low);total+=v*v;}return Math.sqrt(high/total);}
 // Short-window low/mid energy contrast measures the audible separation between burble pulses.
 static double burbleContrast(float[] x){int window=RATE/250;double[] energy=new double[x.length/window];double hi=0,lo=0,kh=1-Math.exp(-2*Math.PI*1000/RATE),kl=1-Math.exp(-2*Math.PI*65/RATE);for(int i=0;i<x.length;i++){hi+=(x[i]-hi)*kh;lo+=(x[i]-lo)*kl;double band=hi-lo;energy[i/window]+=band*band;}Arrays.sort(energy);double loud=Math.sqrt(energy[(int)(energy.length*.90)]/window),quiet=Math.sqrt(energy[(int)(energy.length*.10)]/window);return (loud-quiet)/(loud+quiet);}
 static double cadence(float[] x){double best=-2;int lagBest=0;for(int lag=RATE/16;lag<=RATE/8;lag++){double xy=0,xx=0,yy=0;for(int i=RATE;i<RATE*2;i+=4){double a=x[i],b=x[i-lag];xy+=a*b;xx+=a*a;yy+=b*b;}double corr=xy/Math.sqrt(xx*yy);if(corr>best){best=corr;lagBest=lag;}}return RATE/(double)lagBest;}
 static float[] event(boolean backfire,boolean enabled){EngineSynth s=new EngineSynth(RATE);float[] block=new float[BLOCK],out=new float[RATE];EngineModel.Frame warm=frame(4400,.05,0);for(int k=0;k<100;k++)s.render(warm,block);for(int k=0;k<100;k++){double blip=enabled&&!backfire&&k<52?Math.sin(Math.PI*k/52.):0;EngineModel.Frame f=new EngineModel.Frame(Profile.get("subaru"),4400,4400,20,0,.05,.5,1,3,0,1,false,true,false,true,"run",-1,blip,backfire&&enabled?1:0);s.render(f,block);System.arraycopy(block,0,out,k*BLOCK,BLOCK);}return out;}
 static double eventDelta(boolean pop){float[] a=event(pop,true),b=event(pop,false);for(int i=0;i<a.length;i++)a[i]-=b[i];return rms(a,0,pop?RATE/5:RATE/2);}
 static void driving(File dir)throws IOException{EngineModel m=new EngineModel();m.setMode(false);m.start();EngineSynth s=new EngineSynth(RATE);float[] block=new float[BLOCK],out=new float[RATE*40];for(int k=0;k<4000;k++){double t=k*.01,v=t<3?0:t<20?(t-3)*2.3:t<22?39.1:t<37?Math.max(0,39.1-(t-22)*2.8):0;long now=10000+k*10;m.stepVehicle(.01,new VehicleSnapshot(t>=3&&t<20?80:0,now,t>=22&&t<37?14.84375:0,now,v,now,t>=22&&t<37?1:0,now),now);s.render(m.frame,block);System.arraycopy(block,0,out,k*BLOCK,BLOCK);}wav(new File(dir,"subaru-driving.wav"),out);}
 static void burbleDemo(File dir)throws IOException{EngineSynth s=new EngineSynth(RATE);float[] block=new float[BLOCK],out=new float[RATE*12];for(int k=-100;k<1200;k++){s.render(frame(k>=600&&k<1000?1200:820,k>=600&&k<1000?.25:.12,0),block);if(k>=0)System.arraycopy(block,0,out,k*BLOCK,BLOCK);}wav(new File(dir,"subaru-burble.wav"),out);}
 static void le(DataOutputStream d,int n,int bytes)throws IOException{for(int k=0;k<bytes;k++)d.write(n>>>(8*k)&255);}
 static void wav(File path,float[] x)throws IOException{try(DataOutputStream d=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(path)))){d.writeBytes("RIFF");le(d,36+x.length*2,4);d.writeBytes("WAVEfmt ");le(d,16,4);le(d,1,2);le(d,1,2);le(d,RATE,4);le(d,RATE*2,4);le(d,2,2);le(d,16,2);d.writeBytes("data");le(d,x.length*2,4);for(float v:x)le(d,EngineSynth.pcm(v,.7),2);}}
 public static void main(String[] args)throws Exception{File dir=new File(args[0]);dir.mkdirs();float[] idle=dry(820),mid=dry(1800),vent=bov();double peak=0;for(float[] x:new float[][]{idle,mid,vent})for(float v:x){if(!Float.isFinite(v))throw new AssertionError("nonfinite audio");peak=Math.max(peak,Math.abs(v));}double first=rms(vent,0,RATE/5),tail=rms(vent,RATE/2,RATE);int last=0;for(int k=0;k<400;k++)if(rms(vent,k*BLOCK,(k+1)*BLOCK)>.001)last=k+1;wav(new File(dir,"subaru-idle.wav"),idle);wav(new File(dir,"subaru-1800rpm.wav"),mid);wav(new File(dir,"subaru-bov-isolated.wav"),vent);driving(dir);burbleDemo(dir);System.out.printf(Locale.US,"{\"idleBodyRms\":%.9f,\"midBodyRms\":%.9f,\"idleCadenceHz\":%.6f,\"burbleContrast\":%.6f,\"idleHighBandRatio\":%.6f,\"revMatchDeltaRms\":%.6f,\"backfireDeltaRms\":%.6f,\"bovFirst200msRms\":%.9f,\"bov500to1000msRms\":%.9f,\"bovAudibleTailMs\":%d,\"maxAbsoluteFloat\":%.9f}%n",body(idle),body(mid),cadence(idle),burbleContrast(idle),highRatio(idle),eventDelta(false),eventDelta(true),first,tail,last*10,peak);}
}
